package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import jakarta.servlet.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
@RestController @ConditionalOnProperty(prefix="medical.runtime-retention",name="enabled",havingValue="true")
public final class RuntimeRetentionController {
 private final ApplicationSessionIdentity identities;private final RuntimeRetentionService service;private final PermissionSchema json;private final RuntimeRetentionReads reads;private final RuntimeRetentionDecisions decisions;
 public RuntimeRetentionController(ApplicationSessionIdentity identities,RuntimeRetentionService service,PermissionSchema json,RuntimeRetentionReads reads,RuntimeRetentionDecisions decisions){this.reads=reads;this.decisions=decisions;this.identities=identities;this.service=service;this.json=json;}
 @PostMapping(value="/api/runtime-retention-policies",consumes="application/json") @ResponseStatus(org.springframework.http.HttpStatus.CREATED)
 public JsonNode approve(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String context=headers(request);String key=SimulationInputArtifactController.one(request,"Idempotency-Key");var actor=identities.requireCurrent(request,auth);if(request.getContentLengthLong()>65536)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);byte[] body=request.getInputStream().readNBytes(65537);if(body.length>65536)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);return envelope(service.approve(actor,context,key,body),response);}
 @GetMapping("/api/runtime-retention-policy-operations") public JsonNode recover(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String context=headers(request);if(request.getContentLengthLong()>0||request.getHeader("Transfer-Encoding")!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);return envelope(service.recover(identities.requireCurrent(request,auth),context,SimulationInputArtifactController.one(request,"Idempotency-Key")),response);}
 @GetMapping("/api/runtime-retention-policies/{id}") public JsonNode read(@PathVariable String id,HttpServletRequest request,HttpServletResponse response,Authentication auth){String c=headers(request);noBody(request);return envelope(reads.read(identities.requireCurrent(request,auth),c,id),response);}
 @GetMapping("/api/runtime-retention-policies") public JsonNode list(HttpServletRequest request,HttpServletResponse response,Authentication auth){String c=common(request);noBody(request);for(String key:request.getParameterMap().keySet())if(!java.util.Set.of("scope","project_id","limit","after").contains(key)||request.getParameterValues(key).length!=1)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);String scope=request.getParameter("scope"),limit=request.getParameter("limit");if(scope==null||limit!=null&&!limit.matches("[1-9]|1[0-9]|20"))throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);return envelope(reads.list(identities.requireCurrent(request,auth),c,scope,request.getParameter("project_id"),limit==null?10:Integer.parseInt(limit),request.getParameter("after")),response);}
 @PostMapping(value="/api/runtime-retention-retirements",consumes="application/json") public JsonNode retire(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String c=headers(request);var actor=identities.requireCurrent(request,auth);if(request.getContentLengthLong()>65536)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);byte[] body=request.getInputStream().readNBytes(65537);if(body.length>65536)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);return envelope(decisions.retire(actor,c,SimulationInputArtifactController.one(request,"Idempotency-Key"),body),response);}
 @GetMapping("/api/runtime-retention-retirement-operations") public JsonNode recoverRetirement(HttpServletRequest request,HttpServletResponse response,Authentication auth){String c=headers(request);noBody(request);return envelope(decisions.recover(identities.requireCurrent(request,auth),c,SimulationInputArtifactController.one(request,"Idempotency-Key")),response);}
 private static void noBody(HttpServletRequest request){if(request.getContentLengthLong()>0||request.getHeader("Transfer-Encoding")!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}
 private static String headers(HttpServletRequest request){if(request.getQueryString()!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);return common(request);}
 private static String common(HttpServletRequest request){if(!"1.0.0".equals(SimulationInputArtifactController.one(request,"X-Schema-Version")))throw new SchemaRejection(ErrorCode.SCHEMA_UNSUPPORTED);String context=SimulationInputArtifactController.one(request,"X-Context-Revision");PermissionSchema.revision(context);return context;}
 private JsonNode envelope(JsonNode data,HttpServletResponse response){String id=java.util.UUID.randomUUID().toString();response.setHeader("Cache-Control","no-store");response.setHeader("X-Schema-Version","1.0.0");response.setHeader("X-Resource-Revision","1");response.setHeader("X-Request-Id",id);var result=json.object();result.put("schema_version","1.0.0");result.put("request_id",id);result.put("resource_revision","1");result.set("data",data);return result;}
 @ExceptionHandler(SchemaRejection.class) void invalid(SchemaRejection failure,HttpServletResponse response)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(response,422,failure.code());}
 @ExceptionHandler(TenantAccessException.class) void denied(TenantAccessException failure,HttpServletResponse response)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(response,SimulationRuleVersionController.errorStatus(failure.code()),failure.code());}
}
